#include <iostream>
#include <math.h>

// 使用欧几里得算法计算最大公约数
int gcd(int a, int b) {
    // 欧几里得算法：如果b为0，则a就是最大公约数；否则，最大公约数等于b和a除以b的余数的最大公约数
    if (b == 0) {
        return a;
    } else {
        return gcd(b, a % b);
    }
}

int main() {
    int num1, num2;
    std::cout << "请输入两个整数：";
    std::cin >> num1 >> num2;

    // 计算并输出最大公约数
    int result = gcd(num1, num2);
    std::cout << "这两个数的最大公约数是：" << result << std::endl;

    return 0;
}
```

