#include <iostream>
#include <cctype> // for isdigit function

// Function to check if input is a number
bool isNumber(const std::string& str) {
    for (char c : str) {
        if (!isdigit(c)) return false;
    }
    return true;
}

// Function to perform arithmetic operations
double calculate(double num1, double num2, char op) {
    switch (op) {
        case '+':
            return num1 + num2;
        case '-':
            return num1 - num2;
        case '*':
            return num1 * num2;
        case '/':
            if (num2 != 0) return num1 / num2;
            else throw std::invalid_argument("Division by zero is not allowed");
        default:
            throw std::invalid_argument("Invalid operator");
    }
}

int main() {
    double num1, num2;
    char op;

    std::cout << "Enter first number: ";
    while (!(std::cin >> num1 && isNumber(std::to_string(num1)))) {
        std::cout << "Invalid input. Please enter a number: ";
        std::cin.clear();
        std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
    }

    std::cout << "Enter second number: ";
    while (!(std::cin >> num2 && isNumber(std::to_string(num2)))) {
        std::cout << "Invalid input. Please enter a number: ";
        std::cin.clear();
        std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
    }

    std::cout << "Enter an operator (+, -, *, /): ";
    while (!(std::cin >> op && (op == '+' || op == '-' || op == '*' || op == '/'))) {
        std::cout << "Invalid input. Please enter a valid operator: ";
        std::cin.clear();
        std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
    }

    try {
        double result = calculate(num1, num2, op);
        std::cout << "Result: " << result << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
